function(container, apiUrl, tables) {
  // テーブルインデックス
  const CONTACT_HISTORY_TABLE = 0;
  const CLIENT_TABLE = 1;
  const PROJECT_TABLE = 2;
  const ORDER_TABLE = 3;
  const POLICY_TABLE = 4;

  // フォーム要素の取得
  const clientSelect = container.querySelector("#client-select");
  const projectSelect = container.querySelector("#project-select");
  const contactDatetime = container.querySelector("#contact-datetime");
  const contactMethod = container.querySelector("#contact-method");
  const contactContent = container.querySelector("#contact-content");
  const policySelect = container.querySelector("#policy-select");
  const nextContactDate = container.querySelector("#next-contact-date");
  const fileUpload = container.querySelector("#file-upload");
  const fileList = container.querySelector("#file-list");
  const userDisplay = container.querySelector("#user-display");
  const btnSave = container.querySelector("#btn-save");
  const btnCancel = container.querySelector("#btn-cancel");

  // プレビュー要素
  const clientPreview = container.querySelector("#client-preview");
  const projectPreview = container.querySelector("#project-preview");
  const orderPreview = container.querySelector("#order-preview");
  const recentHistory = container.querySelector("#recent-history");

  // 初期データの取得
  const contactHistoryData = tables[CONTACT_HISTORY_TABLE]?.records || [];
  const clientData = tables[CLIENT_TABLE]?.records || [];
  const projectData = tables[PROJECT_TABLE]?.records || [];
  const orderData = tables[ORDER_TABLE]?.records || [];
  const policyData = tables[POLICY_TABLE]?.records || [];

  // ユーザー情報の表示（ダミー）
  userDisplay.textContent = "営業太郎（営業部）";

  // クライアント選択時のプレビュー更新
  clientSelect.addEventListener("change", () => {
    const selectedId = clientSelect.value;
    if (!selectedId) {
      clientPreview.innerHTML = '<div style="color: var(--text-muted);">クライアントを選択してください</div>';
      projectPreview.innerHTML = '<div style="color: var(--text-muted);">案件を選択してください</div>';
      orderPreview.innerHTML = '<div style="color: var(--text-muted);">関連する受注情報はありません</div>';
      recentHistory.innerHTML = '<div style="color: var(--text-muted);">対応履歴はありません</div>';
      return;
    }

    const client = clientData.find(c => c.id === selectedId || c.クライアントID === selectedId);
    if (client) {
      clientPreview.innerHTML = `
        <div><strong style="color: var(--text);">${client.クライアント名 || client.name || "N/A"}</strong></div>
        <div style="color: var(--text-muted);">業種: ${client.業種 || client.industry || "N/A"}</div>
        <div style="color: var(--text-muted);">代表者: ${client.代表者名 || client.representative || "N/A"}</div>
        <div style="color: var(--text-muted);">ステータス: ${client.ステータス || client.status || "N/A"}</div>
      `;
    }

    // 関連する案件を表示
    const relatedProjects = projectData.filter(p => p.クライアントID === selectedId || p.clientId === selectedId);
    if (relatedProjects.length > 0) {
      projectPreview.innerHTML = relatedProjects.slice(0, 2).map(p => `
        <div style="padding: 0.5rem; background: rgba(0,0,0,0.15); border-radius: 0.25rem;">
          <div style="color: var(--text); font-weight: 500;">${p.案件名 || p.projectName || "N/A"}</div>
          <div style="color: var(--text-muted); font-size: 0.8rem;">ステータス: ${p.ステータス || p.status || "N/A"}</div>
        </div>
      `).join("");
    } else {
      projectPreview.innerHTML = '<div style="color: var(--text-muted);">関連する案件はありません</div>';
    }

    // 関連する受注を表示
    const relatedOrders = orderData.filter(o => o.クライアントID === selectedId || o.clientId === selectedId);
    if (relatedOrders.length > 0) {
      orderPreview.innerHTML = relatedOrders.slice(0, 1).map(o => `
        <div style="padding: 0.5rem; background: rgba(0,0,0,0.15); border-radius: 0.25rem;">
          <div style="color: var(--text); font-weight: 500;">${o.商品・サービス名 || o.productName || "N/A"}</div>
          <div style="color: var(--text-muted); font-size: 0.8rem;">金額: ¥${(o.受注金額 || o.orderAmount || 0).toLocaleString()}</div>
          <div style="color: var(--text-muted); font-size: 0.8rem;">ステータス: ${o.ステータス || o.status || "N/A"}</div>
        </div>
      `).join("");
    } else {
      orderPreview.innerHTML = '<div style="color: var(--text-muted);">関連する受注情報はありません</div>';
    }

    // 最近の対応履歴を表示
    const recentContacts = contactHistoryData
      .filter(h => h.クライアントID === selectedId || h.clientId === selectedId)
      .sort((a, b) => new Date(b.対応日時 || b.contactDatetime) - new Date(a.対応日時 || a.contactDatetime))
      .slice(0, 3);

    if (recentContacts.length > 0) {
      recentHistory.innerHTML = recentContacts.map(h => `
        <div style="padding: 0.5rem; border-left: 2px solid var(--primary);">
          <div style="color: var(--text); font-size: 0.8rem; font-weight: 500;">${h.対応種別 || h.contactMethod || "N/A"} - ${new Date(h.対応日時 || h.contactDatetime).toLocaleDateString('ja-JP')}</div>
          <div style="color: var(--text-muted); font-size: 0.75rem; margin-top: 0.25rem;">${(h.対応内容 || h.content || "").substring(0, 50)}...</div>
        </div>
      `).join("");
    } else {
      recentHistory.innerHTML = '<div style="color: var(--text-muted);">対応履歴はありません</div>';
    }
  });

  // ファイルアップロード処理
  fileUpload.addEventListener("change", (e) => {
    const files = Array.from(e.target.files);
    if (files.length > 0) {
      fileList.innerHTML = files.map(f => `<div>📎 ${f.name}</div>`).join("");
    } else {
      fileList.innerHTML = "";
    }
  });

  // 登録ボタン
  btnSave.addEventListener("click", async () => {
    const clientId = clientSelect.value;
    const projectId = projectSelect.value;
    const datetime = contactDatetime.value;
    const method = contactMethod.value;
    const content = contactContent.value;
    const policyId = policySelect.value;
    const nextDate = nextContactDate.value;

    // バリデーション
    if (!clientId || !datetime || !method || !content) {
      alert("必須項目を入力してください");
      return;
    }

    // 保存データの構築
    const newRecord = {
      クライアントID: clientId,
      案件ID: projectId || null,
      ユーザーID: "current-user-id",
      対応種別: method,
      対応日時: new Date(datetime).toISOString(),
      対応内容: content,
      次回対応予定日: nextDate ? new Date(nextDate).toISOString() : null,
      対応方針ID: policyId || null,
      ステータス: "完了",
      成果: null,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: "current-user-id"
    };

    // API保存
    const saved = await window.aivicApi.save(CONTACT_HISTORY_TABLE, newRecord);
    if (saved) {
      alert("対応履歴を登録しました");
      // フォームをリセット
      clientSelect.value = "";
      projectSelect.value = "";
      contactDatetime.value = "";
      contactMethod.value = "";
      contactContent.value = "";
      policySelect.value = "";
      nextContactDate.value = "";
      fileUpload.value = "";
      fileList.innerHTML = "";
      clientPreview.innerHTML = '<div style="color: var(--text-muted);">クライアントを選択してください</div>';
      projectPreview.innerHTML = '<div style="color: var(--text-muted);">案件を選択してください</div>';
      orderPreview.innerHTML = '<div style="color: var(--text-muted);">関連する受注情報はありません</div>';
      recentHistory.innerHTML = '<div style="color: var(--text-muted);">対応履歴はありません</div>';
    }
  });

  // キャンセルボタン
  btnCancel.addEventListener("click", () => {
    if (confirm("入力内容を破棄してもよろしいですか？")) {
      window.showScreen("scr-1781408840123"); // 対応履歴・対応方針管理画面へ遷移
    }
  });
}

function(container, apiUrl, tables) {
  const clientSelect = container.querySelector("#client-select");
  const policiesList = container.querySelector("#policies-list");
  const policyNameInput = container.querySelector("#policy-name");
  const policyDescInput = container.querySelector("#policy-description");
  const frequencySelect = container.querySelector("#frequency");
  const assignedUserSelect = container.querySelector("#assigned-user");
  const startDateInput = container.querySelector("#start-date");
  const endDateInput = container.querySelector("#end-date");
  const templateSelect = container.querySelector("#template-select");
  const historyPreview = container.querySelector("#history-preview");
  const projectsTbody = container.querySelector("#projects-tbody");
  const btnNewPolicy = container.querySelector("#btn-new-policy");
  const btnSavePolicy = container.querySelector("#btn-save-policy");
  const btnCancel = container.querySelector("#btn-cancel");

  let currentPolicyId = null;
  let currentClientId = null;

  // 1. 方針一覧を再描画する関数
  function renderPolicies(policies) {
    policiesList.innerHTML = policies.map(p => `
      <div class="policy-item" data-id="${p.id}" style="padding: 8px; background: rgba(212,175,55,0.08); border-left: 3px solid #d4af37; border-radius: 3px; cursor: pointer; transition: background 0.2s;" data-testid="policy-item-${p.id}">
        <div style="font-size: 12px; font-weight: 600; color: var(--text);">${p.方針名 || "無名"}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">優先度: ${["高", "中", "低"][parseInt(p.優先度) - 1] || "未設定"}</div>
      </div>
    `).join("");
  }

  // 2. 対応履歴プレビューを描画
  function renderHistoryPreview(histories) {
    if (!histories || histories.length === 0) {
      historyPreview.innerHTML = '<div style="padding: 8px; text-align: center; color: var(--text-muted);">履歴がありません</div>';
      return;
    }
    historyPreview.innerHTML = histories.slice(0, 5).map(h => `
      <div style="padding: 6px; border-bottom: 1px solid rgba(255,255,255,0.1);">
        <div style="font-size: 11px; color: var(--text);">${h.対応種別 || "対応"} - ${h.対応日時 ? new Date(h.対応日時).toLocaleDateString('ja-JP') : "日時未設定"}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${(h.対応内容 || "").substring(0, 50)}...</div>
      </div>
    `).join("");
  }

  // 3. 関連案件を描画
  function renderProjects(projects) {
    if (!projects || projects.length === 0) {
      projectsTbody.innerHTML = '<tr><td colspan="3" style="padding: 8px; text-align: center; color: var(--text-muted);">案件がありません</td></tr>';
      return;
    }
    projectsTbody.innerHTML = projects.map(p => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.1);">
        <td style="padding: 6px; color: var(--text);">${p.案件名 || ""}</td>
        <td style="padding: 6px; color: var(--text-muted); font-size: 11px;">${p.ステータス || ""}</td>
        <td style="padding: 6px; text-align: right; color: var(--text);">${p.予想金額 ? "¥" + p.予想金額.toLocaleString() : "-"}</td>
      </tr>
    `).join("");
  }

  // 4. フォームをリセット
  function resetForm() {
    policyNameInput.value = "";
    policyDescInput.value = "";
    frequencySelect.value = "";
    assignedUserSelect.value = "";
    startDateInput.value = "";
    endDateInput.value = "";
    templateSelect.value = "";
    container.querySelectorAll("input[name='priority']").forEach(r => r.checked = false);
    container.querySelectorAll("input[type='checkbox']").forEach(c => c.checked = false);
    currentPolicyId = null;
  }

  // 5. 初期データ読み込み
  if (tables[0] && tables[0].records) {
    renderPolicies(tables[0].records);
  }

  // 6. クライアント選択時の処理
  clientSelect.addEventListener("change", async () => {
    currentClientId = clientSelect.value;
    resetForm();
    policiesList.innerHTML = "";

    if (!currentClientId) return;

    // 該当クライアントの方針を取得
    const allPolicies = await window.aivicApi.list(0);
    if (allPolicies) {
      const clientPolicies = allPolicies.filter(p => p.クライアントID === currentClientId);
      renderPolicies(clientPolicies);
    }
  });

  // 7. 方針アイテムクリック時の処理
  container.addEventListener("click", async (e) => {
    const policyItem = e.target.closest(".policy-item");
    if (policyItem) {
      currentPolicyId = policyItem.dataset.id;

      // 該当方針の詳細を表示
      const allPolicies = await window.aivicApi.list(0);
      const policy = allPolicies.find(p => p.id === currentPolicyId);

      if (policy) {
        policyNameInput.value = policy.方針名 || "";
        policyDescInput.value = policy.方針内容 || "";
        frequencySelect.value = policy.対応頻度 || "";
        assignedUserSelect.value = policy.担当者ID || "";
        startDateInput.value = policy.開始日 ? policy.開始日.split("T")[0] : "";
        endDateInput.value = policy.終了日 ? policy.終了日.split("T")[0] : "";

        const priority = policy.優先度;
        if (priority) {
          container.querySelector(`input[name="priority"][value="${priority}"]`).checked = true;
        }

        // 対応履歴を取得（テーブル1と仮定）
        const histories = await window.aivicApi.list(1);
        if (histories) {
          const clientHistories = histories.filter(h => h.クライアントID === currentClientId);
          renderHistoryPreview(clientHistories);
        }

        // 関連案件を取得（テーブル2と仮定）
        const projects = await window.aivicApi.list(2);
        if (projects) {
          const clientProjects = projects.filter(p => p.クライアントID === currentClientId);
          renderProjects(clientProjects);
        }
      }
    }
  });

  // 8. 新規方針作成ボタン
  btnNewPolicy.addEventListener("click", () => {
    if (!currentClientId) {
      alert("先にクライアントを選択してください");
      return;
    }
    currentPolicyId = null;
    resetForm();
  });

  // 9. 保存ボタン
  btnSavePolicy.addEventListener("click", async () => {
    if (!currentClientId) {
      alert("クライアントを選択してください");
      return;
    }
    if (!policyNameInput.value.trim()) {
      alert("方針名を入力してください");
      return;
    }
    if (!policyDescInput.value.trim()) {
      alert("方針説明を入力してください");
      return;
    }
    if (!startDateInput.value) {
      alert("開始日を選択してください");
      return;
    }

    const priority = container.querySelector("input[name='priority']:checked")?.value || "2";
    const channels = Array.from(container.querySelectorAll("input[type='checkbox']:checked")).map(c => c.value).join(",");

    const policyData = {
      クライアントID: currentClientId,
      方針名: policyNameInput.value,
      方針内容: policyDescInput.value,
      優先度: priority,
      対応頻度: frequencySelect.value,
      担当者ID: assignedUserSelect.value,
      開始日: startDateInput.value,
      終了日: endDateInput.value,
      対応チャネル: channels,
      ステータス: "有効"
    };

    let result;
    if (currentPolicyId) {
      result = await window.aivicApi.update(0, currentPolicyId, policyData);
    } else {
      result = await window.aivicApi.save(0, policyData);
    }

    if (result) {
      alert(currentPolicyId ? "方針を更新しました" : "方針を作成しました");
      const allPolicies = await window.aivicApi.list(0);
      if (allPolicies) {
        const clientPolicies = allPolicies.filter(p => p.クライアントID === currentClientId);
        renderPolicies(clientPolicies);
      }
      resetForm();
    }
  });

  // 10. キャンセルボタン
  btnCancel.addEventListener("click", () => {
    resetForm();
  });

  // 11. 削除ボタン（右クリックメニューまたは別途実装）
  container.addEventListener("contextmenu", async (e) => {
    const policyItem = e.target.closest(".policy-item");
    if (policyItem) {
      e.preventDefault();
      if (confirm("この方針を削除しますか？")) {
        await window.aivicApi.delete(0, policyItem.dataset.id);
        const allPolicies = await window.aivicApi.list(0);
        if (allPolicies) {
          const clientPolicies = allPolicies.filter(p => p.クライアントID === currentClientId);
          renderPolicies(clientPolicies);
        }
        resetForm();
      }
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#order-tbody");
  const clientPanel = container.querySelector("#client-info-panel");
  const clientDetailContent = container.querySelector("#client-detail-content");
  const clientNameInput = container.querySelector("[data-testid='client-name-input']");
  const projectNameInput = container.querySelector("[data-testid='project-name-input']");
  const orderDateFrom = container.querySelector("[data-testid='order-date-from']");
  const orderDateTo = container.querySelector("[data-testid='order-date-to']");
  const statusFilter = container.querySelector("[data-testid='status-filter']");
  const salesPersonFilter = container.querySelector("[data-testid='sales-person-filter']");
  const amountMin = container.querySelector("[data-testid='amount-min']");
  const amountMax = container.querySelector("[data-testid='amount-max']");
  const searchBtn = container.querySelector("[data-testid='search-button']");
  const resetBtn = container.querySelector("[data-testid='reset-button']");
  const exportBtn = container.querySelector("[data-testid='export-csv-button']");
  const viewClientDetailBtn = container.querySelector("[data-testid='view-client-detail-btn']");
  const viewInteractionsBtn = container.querySelector("[data-testid='view-interactions-btn']");

  let allOrders = [];
  let allClients = [];
  let allInteractions = [];
  let selectedOrderId = null;

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const orderDate = r.受注日 ? new Date(r.受注日).toLocaleDateString('ja-JP') : '—';
      const amount = r.受注金額 ? `¥${Number(r.受注金額).toLocaleString()}` : '—';
      return `
        <tr data-id="${r.受注ID || ''}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background=''">
          <td style="padding: 8px 10px; color: var(--text); font-size: 12px;">${r.受注ID || '—'}</td>
          <td style="padding: 8px 10px; color: var(--text); font-size: 12px;">${r.クライアント名 || '—'}</td>
          <td style="padding: 8px 10px; color: var(--text); font-size: 12px;">${r.案件名 || '—'}</td>
          <td style="padding: 8px 10px; color: var(--text); font-size: 12px;">${orderDate}</td>
          <td style="padding: 8px 10px; color: var(--text); font-size: 12px; text-align: right;">${amount}</td>
          <td style="padding: 8px 10px; color: var(--text); font-size: 12px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${r.ステータス === '完了' ? 'rgba(76,175,80,0.2)' : r.ステータス === 'キャンセル' ? 'rgba(244,67,54,0.2)' : 'rgba(255,193,7,0.2)'}; color: ${r.ステータス === '完了' ? '#4caf50' : r.ステータス === 'キャンセル' ? '#f44336' : '#ffc107'};">${r.ステータス || '—'}</span>
          </td>
          <td style="padding: 8px 10px; color: var(--text); font-size: 12px;">${r.営業担当者 || '—'}</td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    const orders = await window.aivicApi.list(0);
    if (orders) {
      allOrders = orders;
      renderRows(allOrders);
    }
  }

  // 3. クライアント情報パネルを表示
  async function showClientDetail(orderId) {
    selectedOrderId = orderId;
    const order = allOrders.find(o => o.受注ID === orderId);
    if (!order) return;

    // クライアント情報を取得
    const clients = await window.aivicApi.list(1);
    const client = clients ? clients.find(c => c.クライアント名 === order.クライアント名) : null;

    // 対応履歴を取得
    const interactions = await window.aivicApi.list(2);
    const orderInteractions = interactions ? interactions.filter(i => i.クライアント名 === order.クライアント名) : [];

    // クライアント情報を表示
    if (client) {
      container.querySelector("#client-name-detail").textContent = client.クライアント名 || '—';
      container.querySelector("#client-industry-detail").textContent = client.業種 || '—';
      container.querySelector("#client-rep-detail").textContent = client.代表者名 || '—';
      container.querySelector("#client-email-detail").textContent = client.メールアドレス || '—';
      container.querySelector("#client-phone-detail").textContent = client.電話番号 || '—';
      container.querySelector("#client-address-detail").textContent = client.住所 || '—';
    }

    // 受注詳細を表示
    container.querySelector("#order-product-detail").textContent = order.商品・サービス名 || '—';
    container.querySelector("#order-amount-detail").textContent = order.受注金額 ? `¥${Number(order.受注金額).toLocaleString()}` : '—';
    container.querySelector("#order-tax-detail").textContent = order.税額 ? `¥${Number(order.税額).toLocaleString()}` : '—';
    container.querySelector("#order-total-detail").textContent = order.税込金額 ? `¥${Number(order.税込金額).toLocaleString()}` : '—';
    container.querySelector("#order-due-date-detail").textContent = order.納期 ? new Date(order.納期).toLocaleDateString('ja-JP') : '—';
    container.querySelector("#order-delivery-date-detail").textContent = order.納品日 ? new Date(order.納品日).toLocaleDateString('ja-JP') : '—';
    container.querySelector("#order-notes-detail").textContent = order.備考 || '—';

    // 対応履歴を表示
    const historyHtml = orderInteractions.length > 0
      ? orderInteractions.slice(0, 5).map(i => `
          <div style="padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.05);">
            <div style="font-weight: 500; color: var(--text);">${i.対応種別 || '—'}</div>
            <div style="font-size: 11px; color: var(--text-muted);">${i.対応日時 ? new Date(i.対応日時).toLocaleDateString('ja-JP') : '—'}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${(i.対応内容 || '').substring(0, 50)}${(i.対応内容 || '').length > 50 ? '...' : ''}</div>
          </div>
        `).join("")
      : '<div style="text-align: center; padding: 10px; color: var(--text-muted); font-size: 11px;">対応履歴なし</div>';

    container.querySelector("#interaction-history").innerHTML = historyHtml;
    clientDetailContent.style.display = "block";
  }

  // 4. 検索実行
  searchBtn.addEventListener("click", async () => {
    const clientName = clientNameInput.value.toLowerCase();
    const projectName = projectNameInput.value.toLowerCase();
    const dateFrom = orderDateFrom.value ? new Date(orderDateFrom.value) : null;
    const dateTo = orderDateTo.value ? new Date(orderDateTo.value) : null;
    const status = statusFilter.value;
    const salesperson = salesPersonFilter.value;
    const minAmount = amountMin.value ? parseInt(amountMin.value) : null;
    const maxAmount = amountMax.value ? parseInt(amountMax.value) : null;

    const filtered = allOrders.filter(o => {
      if (clientName && !(o.クライアント名 || '').toLowerCase().includes(clientName)) return false;
      if (projectName && !(o.案件名 || '').toLowerCase().includes(projectName)) return false;
      if (dateFrom && new Date(o.受注日) < dateFrom) return false;
      if (dateTo && new Date(o.受注日) > dateTo) return false;
      if (status && o.ステータス !== status) return false;
      if (salesperson && o.営業担当者 !== salesperson) return false;
      if (minAmount !== null && (o.受注金額 || 0) < minAmount) return false;
      if (maxAmount !== null && (o.受注金額 || 0) > maxAmount) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 5. リセット
  resetBtn.addEventListener("click", () => {
    clientNameInput.value = "";
    projectNameInput.value = "";
    orderDateFrom.value = "";
    orderDateTo.value = "";
    statusFilter.value = "";
    salesPersonFilter.value = "";
    amountMin.value = "";
    amountMax.value = "";
    renderRows(allOrders);
    clientDetailContent.style.display = "none";
  });

  // 6. CSV エクスポート
  exportBtn.addEventListener("click", () => {
    if (allOrders.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注ID", "クライアント名", "案件名", "受注日", "受注金額", "ステータス", "営業担当者"];
    const rows = allOrders.map(o => [
      o.受注ID || "",
      o.クライアント名 || "",
      o.案件名 || "",
      o.受注日 ? new Date(o.受注日).toLocaleDateString('ja-JP') : "",
      o.受注金額 || "",
      o.ステータス || "",
      o.営業担当者 || ""
    ]);

    const csv = "\uFEFF" + [headers, ...rows].map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `受注履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 7. 行クリックでクライアント詳細表示
  container.addEventListener("click", async e => {
    const tr = e.target.closest("tr[data-id]");
    if (tr) {
      const orderId = tr.dataset.id;
      await showClientDetail(orderId);
    }
  });

  // 8. クライアント詳細画面へ遷移
  viewClientDetailBtn.addEventListener("click", () => {
    if (selectedOrderId) {
      const order = allOrders.find(o => o.受注ID === selectedOrderId);
      if (order) {
        window.showScreen("scr-1781408824557");
      }
    }
  });

  // 9. 対応履歴画面へ遷移
  viewInteractionsBtn.addEventListener("click", () => {
    if (selectedOrderId) {
      window.showScreen("scr-1781408840123");
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  const clientTbody = container.querySelector("#client-tbody");
  const detailContent = container.querySelector("#detail-content");
  const policyContent = container.querySelector("#policy-content");
  const historyTimeline = container.querySelector("#history-timeline");
  const projectList = container.querySelector("#project-list");
  const orderSummary = container.querySelector("#order-summary");
  const orderCount = container.querySelector("#order-count");
  const orderTotal = container.querySelector("#order-total");

  let selectedClientId = null;
  let clientsData = [];
  let historiesData = [];
  let policiesData = [];
  let projectsData = [];
  let ordersData = [];

  // テーブルインデックスの取得
  const clientTableIdx = tables.findIndex(t => t.tableName === "クライアント") ?? 0;
  const historyTableIdx = tables.findIndex(t => t.tableName === "対応履歴") ?? 1;
  const policyTableIdx = tables.findIndex(t => t.tableName === "対応方針") ?? 2;
  const projectTableIdx = tables.findIndex(t => t.tableName === "案件") ?? 3;
  const orderTableIdx = tables.findIndex(t => t.tableName === "受注") ?? 4;

  // 1. クライアント一覧を再描画
  function renderClients(rows) {
    clientTbody.innerHTML = rows.map(r => `
      <tr class="client-row" data-id="${r.クライアントID || r.id || ''}" style="display: block; padding: 8px 6px; border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.15s; border-radius: 3px;">
        <td style="display: block; color: var(--text); font-weight: 500; margin-bottom: 2px;">${r.クライアント名 || r.name || '(無名)'}</td>
        <td style="display: block; color: var(--text-muted); font-size: 10px;">${r.業種 || ''}</td>
        <td style="display: block; color: var(--text-muted); font-size: 10px; margin-top: 2px;">
          <span style="display: inline-block; background: rgba(255,165,0,0.15); color: #ffb347; padding: 2px 6px; border-radius: 2px; font-size: 9px;">
            ${r.ステータス || '未分類'}
          </span>
        </td>
      </tr>
    `).join("");
  }

  // 2. クライアント詳細を表示
  function showClientDetail(clientId) {
    selectedClientId = clientId;
    const client = clientsData.find(c => (c.クライアントID || c.id) === clientId);
    if (!client) {
      detailContent.innerHTML = '<p style="color: var(--text-muted);">クライアント情報が見つかりません</p>';
      return;
    }

    detailContent.innerHTML = `
      <div style="display: grid; gap: 6px;">
        <div><span style="color: var(--text-muted); font-size: 10px;">企業名</span><br/><span style="color: var(--text); font-weight: 500;">${client.クライアント名 || client.name || ''}</span></div>
        <div><span style="color: var(--text-muted); font-size: 10px;">業種</span><br/><span style="color: var(--text);">${client.業種 || '-'}</span></div>
        <div><span style="color: var(--text-muted); font-size: 10px;">代表者</span><br/><span style="color: var(--text);">${client.代表者名 || '-'}</span></div>
        <div><span style="color: var(--text-muted); font-size: 10px;">メール</span><br/><span style="color: var(--text); word-break: break-all;">${client.メールアドレス || '-'}</span></div>
        <div><span style="color: var(--text-muted); font-size: 10px;">電話</span><br/><span style="color: var(--text);">${client.電話番号 || '-'}</span></div>
        <div><span style="color: var(--text-muted); font-size: 10px;">ステータス</span><br/><span style="color: var(--text);">${client.ステータス || '-'}</span></div>
        <div><span style="color: var(--text-muted); font-size: 10px;">推定売上</span><br/><span style="color: var(--text); font-weight: 600;">¥${(client.推定売上額 || 0).toLocaleString()}</span></div>
      </div>
    `;

    // 対応方針を表示
    const policy = policiesData.find(p => (p.クライアントID || p.client_id) === clientId);
    if (policy) {
      policyContent.innerHTML = `
        <div style="display: grid; gap: 6px;">
          <div><span style="color: var(--text-muted); font-size: 10px;">方針名</span><br/><span style="color: var(--text); font-weight: 500;">${policy.方針名 || policy.対応方針名 || '-'}</span></div>
          <div><span style="color: var(--text-muted); font-size: 10px;">優先度</span><br/>
            <span style="display: inline-block; background: ${policy.優先度 === 1 ? 'rgba(255,0,0,0.15)' : 'rgba(255,165,0,0.15)'}; color: ${policy.優先度 === 1 ? '#ff6b6b' : '#ffb347'}; padding: 2px 6px; border-radius: 2px; font-size: 10px;">
              ${['', '高', '中', '低'][policy.優先度 || 2] || '-'}
            </span>
          </div>
          <div><span style="color: var(--text-muted); font-size: 10px;">対応頻度</span><br/><span style="color: var(--text);">${policy.対応頻度 || '-'}</span></div>
          <div><span style="color: var(--text-muted); font-size: 10px;">ステータス</span><br/><span style="color: var(--text);">${policy.ステータス || policy.対応方針ステータス || '-'}</span></div>
        </div>
      `;
    } else {
      policyContent.innerHTML = '<p style="color: var(--text-muted);">対応方針が設定されていません</p>';
    }

    // 対応履歴を表示
    const histories = historiesData.filter(h => (h.クライアントID || h.client_id) === clientId).sort((a, b) => new Date(b.対応日時 || b.created_at) - new Date(a.対応日時 || a.created_at));
    if (histories.length > 0) {
      historyTimeline.innerHTML = histories.slice(0, 5).map(h => `
        <div style="padding: 8px; border-left: 2px solid var(--primary); margin-bottom: 6px; background: rgba(255,165,0,0.05); border-radius: 2px;">
          <div style="color: var(--text); font-weight: 500; font-size: 10px;">${h.対応種別 || h.type || '-'}</div>
          <div style="color: var(--text-muted); font-size: 9px; margin-top: 2px;">${new Date(h.対応日時 || h.created_at).toLocaleDateString('ja-JP')}</div>
          <div style="color: var(--text); font-size: 10px; margin-top: 4px; line-height: 1.4;">${(h.対応内容 || h.content || '').substring(0, 80)}...</div>
        </div>
      `).join("");
    } else {
      historyTimeline.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 20px 0;">対応履歴がありません</div>';
    }

    // 案件を表示
    const projects = projectsData.filter(p => (p.クライアントID || p.client_id) === clientId);
    if (projects.length > 0) {
      projectList.innerHTML = projects.map(p => `
        <div style="padding: 6px; background: rgba(255,165,0,0.08); border-left: 2px solid var(--primary); border-radius: 2px;">
          <div style="color: var(--text); font-weight: 500; font-size: 10px;">${p.案件名 || p.name || '-'}</div>
          <div style="color: var(--text-muted); font-size: 9px; margin-top: 2px;">${p.ステータス || '-'} | 確度: ${p.成約確度 || 0}%</div>
        </div>
      `).join("");
    } else {
      projectList.innerHTML = '<div style="color: var(--text-muted);">案件がありません</div>';
    }

    // 受注情報を表示
    const orders = ordersData.filter(o => (o.クライアントID || o.client_id) === clientId);
    const totalAmount = orders.reduce((sum, o) => sum + (o.受注金額 || o.amount || 0), 0);
    orderCount.textContent = orders.length + '件';
    orderTotal.textContent = '¥' + totalAmount.toLocaleString();
  }

  // 3. 初期データ読み込み
  async function loadAllData() {
    try {
      clientsData = await window.aivicApi.list(clientTableIdx) || tables[clientTableIdx]?.records || [];
      historiesData = await window.aivicApi.list(historyTableIdx) || tables[historyTableIdx]?.records || [];
      policiesData = await window.aivicApi.list(policyTableIdx) || tables[policyTableIdx]?.records || [];
      projectsData = await window.aivicApi.list(projectTableIdx) || tables[projectTableIdx]?.records || [];
      ordersData = await window.aivicApi.list(orderTableIdx) || tables[orderTableIdx]?.records || [];

      renderClients(clientsData);
    } catch (err) {
      console.error("データ読み込みエラー:", err);
      clientsData = tables[clientTableIdx]?.records || [];
      renderClients(clientsData);
    }
  }

  // 4. クライアント行クリック
  container.addEventListener("click", (e) => {
    const row = e.target.closest(".client-row");
    if (row) {
      const clientId = row.dataset.id;
      showClientDetail(clientId);
      document.querySelectorAll(".client-row").forEach(r => r.style.background = "");
      row.style.background = "rgba(255,165,0,0.1)";
    }
  });

  // 5. 検索・フィルター
  function applyFilters() {
    const searchText = container.querySelector("#client-search-input").value.toLowerCase();
    const statusFilter = container.querySelector("#status-filter").value;
    const contractFilter = container.querySelector("#contract-filter").value;

    const filtered = clientsData.filter(c => {
      const matchSearch = !searchText || 
        (c.クライアント名 || c.name || '').toLowerCase().includes(searchText) ||
        (c.業種 || '').toLowerCase().includes(searchText);
      const matchStatus = !statusFilter || (c.ステータス || '') === statusFilter;
      const matchContract = !contractFilter || (c.契約状況 || '') === contractFilter;
      return matchSearch && matchStatus && matchContract;
    });

    renderClients(filtered);
  }

  container.querySelector("#client-search-input").addEventListener("input", applyFilters);
  container.querySelector("#status-filter").addEventListener("change", applyFilters);
  container.querySelector("#contract-filter").addEventListener("change", applyFilters);

  // 6. 更新ボタン
  container.querySelector("#btn-refresh-list").addEventListener("click", loadAllData);

  // 7. アクションボタン
  container.querySelector("#btn-add-client").addEventListener("click", () => {
    window.showScreen("scr-1781408824557"); // クライアント詳細情報画面
  });

  container.querySelector("#btn-add-history").addEventListener("click", () => {
    if (!selectedClientId) {
      alert("クライアントを選択してください");
      return;
    }
    window.showScreen("scr-1781408865891"); // 対応履歴登録画面
  });

  container.querySelector("#btn-add-project").addEventListener("click", () => {
    if (!selectedClientId) {
      alert("クライアントを選択してください");
      return;
    }
    window.showScreen("scr-1781408904580"); // 案件登録画面
  });

  container.querySelector("#btn-add-order").addEventListener("click", () => {
    if (!selectedClientId) {
      alert("クライアントを選択してください");
      return;
    }
    window.showScreen("scr-1781408891768"); // 受注登録画面
  });

  // 初期化
  loadAllData();
}
